/**
 * Typed loader for the gold-standard signature fixtures in this directory.
 * Both files are generated by `scripts/gen-sig-fixtures.mjs` from TronWeb's
 * official signing stack, entirely offline and using only the trivial keys
 * pk=1 / pk=2.
 *
 * - `message.json`     — TIP-191 message signing cases. Each entry pins the
 *   digest, the `r||s||v` signature (0x hex, v ∈ {0x1b,0x1c}) and the
 *   recovered Base58Check address. A case carries either a UTF-8 `message`
 *   or a `{ raw }` `rawHex` byte input.
 * - `transaction.json` — transaction signing cases: one `r||s||v` signature
 *   (bare lowercase hex) per gold-standard transaction `txID`, signed with
 *   pk=1. The first case is the canonical transfer reference vector.
 */
import { readFileSync } from 'node:fs'

/** The private key a fixture was signed with (only the trivial keys). */
export type PrivateKeyLabel = 'pk1' | 'pk2'

/** One TIP-191 message signing case. */
export type SigMessageFixture = {
  /** Human-readable case name. */
  name: string
  /** Which trivial key produced the signature. */
  privateKeyLabel: PrivateKeyLabel
  /** UTF-8 string input (present for text cases). */
  message?: string
  /** `0x`-prefixed raw byte input (present for `{ raw }` cases). */
  rawHex?: string
  /** TIP-191 keccak digest (`0x` hex). */
  digest: string
  /** `r||s||v` signature (`0x` hex, v ∈ {0x1b,0x1c}). */
  signature: string
  /** Base58Check address recovered from the signature. */
  address: string
}

/** One transaction signing case. */
export type SigTransactionFixture = {
  /** Human-readable case name (mirrors the source tx fixture). */
  name: string
  /** Transaction id being signed (bare lowercase hex). */
  txID: string
  /** Which trivial key produced the signature. */
  privateKeyLabel: PrivateKeyLabel
  /** `r||s||v` signature over the txID digest (bare lowercase hex). */
  signature: string
}

/** One deterministic-fuzz TIP-191 message case. */
export type SigFuzzMessageFixture = SigMessageFixture & {
  /** BYTE length of the message input (drives the TIP-191 length prefix). */
  byteLength: number
}

/** One deterministic-fuzz transaction signing case. */
export type SigFuzzTransactionFixture = SigTransactionFixture & {
  /** Whether the fixture's `owner_address` equals this key's signer address. */
  ownerMatches: boolean
}

/** The whole `fuzz.json` corpus (message + transaction differential vectors). */
export type SigFuzzFixtures = {
  meta: {
    seed: number
    messageCount: number
    transactionCount: number
    boundaries: number[]
  }
  messages: SigFuzzMessageFixture[]
  transactions: SigFuzzTransactionFixture[]
}

function readJson<T>(fileName: string): T[] {
  return JSON.parse(
    readFileSync(new URL(fileName, import.meta.url), 'utf8'),
  ) as T[]
}

/** Loads every TIP-191 message signing case. */
export function loadSigMessageFixtures(): SigMessageFixture[] {
  return readJson<SigMessageFixture>('message.json')
}

/** Loads every transaction signing case. */
export function loadSigTransactionFixtures(): SigTransactionFixture[] {
  return readJson<SigTransactionFixture>('transaction.json')
}

/** Loads the deterministic differential-fuzz corpus (`fuzz.json`). */
export function loadSigFuzzFixtures(): SigFuzzFixtures {
  return JSON.parse(
    readFileSync(new URL('fuzz.json', import.meta.url), 'utf8'),
  ) as SigFuzzFixtures
}
